function longestBalancedStretch(s: string): number {
  let best = 0;
  for (let i = 0; i < s.length; i++) {
    let balance = 0;
    for (let j = i; j < s.length; j++) {
      balance += s[j] === "(" ? 1 : -1;
      if (balance < 0) break;
      if (balance === 0) best = Math.max(best, j - i + 1);
    }
  }
  return best;
}

